using System.Collections.Generic;
using System.Text;
using Politicmon.Data;
using UnityEngine;

namespace Politicmon.UI
{
    /// <summary>
    /// The 8x8 proportional bitmap font (Resources/Fonts/pixel8.png + Data/font.json),
    /// generated by tools/gen_font.py. Includes Spanish accents, ñ, ¿ and ¡.
    /// </summary>
    public static class PixelFont
    {
        public const int GlyphHeight = 8;
        public const int LineHeight = 10;

        static Texture2D texture;
        static Dictionary<char, GlyphData> glyphs;

        public static Texture2D Texture
        {
            get
            {
                EnsureLoaded();
                return texture;
            }
        }

        static void EnsureLoaded()
        {
            if (glyphs != null)
                return;
            texture = Resources.Load<Texture2D>("Fonts/pixel8");
            glyphs = new Dictionary<char, GlyphData>();
            var data = JsonUtility.FromJson<FontData>(Resources.Load<TextAsset>("Data/font").text);
            foreach (var g in data.glyphs)
                glyphs[(char)g.code] = g;
        }

        public static bool TryGetGlyph(char c, out GlyphData glyph)
        {
            EnsureLoaded();
            return glyphs.TryGetValue(c, out glyph);
        }

        public static int Advance(char c) => TryGetGlyph(c, out var g) ? g.advance : 3;

        /// <summary>Width in pixels of the longest line.</summary>
        public static int Measure(string text)
        {
            int best = 0;
            int width = 0;
            foreach (char c in text ?? "")
            {
                if (c == '\n')
                {
                    best = Mathf.Max(best, width);
                    width = 0;
                    continue;
                }
                width += Advance(c);
            }
            return Mathf.Max(best, width);
        }

        /// <summary>Word-wraps the text so that no line is wider than maxWidth pixels.</summary>
        public static List<string> Wrap(string text, float maxWidth)
        {
            var lines = new List<string>();
            foreach (var paragraph in (text ?? "").Split('\n'))
            {
                var line = new StringBuilder();
                foreach (var word in paragraph.Split(' '))
                {
                    if (word.Length == 0)
                        continue;
                    string candidate = line.Length == 0 ? word : line + " " + word;
                    if (Measure(candidate) <= maxWidth || line.Length == 0)
                    {
                        line.Clear().Append(candidate);
                    }
                    else
                    {
                        lines.Add(line.ToString());
                        line.Clear().Append(word);
                    }
                }
                lines.Add(line.ToString());
            }
            return lines;
        }
    }
}
